package com.github.nyabanban.fuji.emulator.components.flashimage

import com.github.nyabanban.fuji.emulator.api.*
import org.junit.jupiter.api.Test
import org.junit.jupiter.api.io.TempDir
import java.nio.ByteBuffer
import java.nio.ByteOrder
import java.nio.file.Files
import java.nio.file.Path
import java.security.MessageDigest
import kotlin.test.*

class WritableRegionsTest {
 @TempDir lateinit var temporary:Path
 private val first=0x3dc0000L;private val second=0x3f00000L
 private fun hash(b:ByteArray)=java.util.HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(b))
 private class Context(override val directory:Path,val data:Map<String,Map<String,Any?>> = emptyMap()):ComponentContext {
  val claims=linkedMapOf<String,Any>();override val clock=EmulationClock{0L}
  override fun readData(relative:String)=data.getValue(relative)
  override fun dataPath(relative:String)=directory.resolve(relative).normalize().also{require(it.startsWith(directory))}
  override val ports=object:Ports{override fun<T:Any>register(owner:String,name:String,type:Class<T>,port:T){check(claims.putIfAbsent(name,port)==null)};override fun<T:Any>find(name:String,type:Class<T>):T?=claims[name]?.let{type.cast(it)};override fun removeOwner(owner:String){}}
  override val events=object:EventChannel{override fun publish(event:ComponentEvent){};override fun subscribe(listener:(ComponentEvent)->Unit)=AutoCloseable{}}
 }
 private inner class Fixture(val home:Path){
  val seeds=listOf(ByteArray(8192){-1},ByteArray(8192){0});val identities=listOf(ImageRegionIdentity("primary",first,8192,hash(seeds[0]),"seed-a.img"),ImageRegionIdentity("secondary",second,8192,hash(seeds[1]),"seed-b.img"))
  val context=Context(home)
  init{Files.createDirectories(home);identities.forEachIndexed{i,r->Files.write(home.resolve(r.relativeFile),seeds[i])}}
  fun child(i:Int)=mapOf<String,Any?>("schema" to 1,"profile" to WritableRegion.PROGRAM_PROFILE,"regionId" to identities[i].id,"file" to if(i==0)"copy-a.img" else "copy-b.img","mode" to "create","sha256" to identities[i].sha256,"writableOffset" to(if(i==0)first+4096 else second),"writableLength" to(if(i==0)4096L else 8192L),"programLaw" to WritableRegion.PROGRAM_LAW,"programPageBytes" to 256)
  fun spec(children:List<Map<String,Any?>> = listOf(child(0),child(1)))=mapOf<String,Any?>("schema" to 1,"profile" to WritableRegions.PROFILE,"primaryRegionId" to "primary","regions" to children)
  fun read(at:Long,dst:ByteBuffer){val i=identities.indexOfFirst{at>=it.offset&&at-it.offset+dst.remaining()<=it.length};require(i>=0);dst.put(seeds[i],(at-identities[i].offset).toInt(),dst.remaining())}
  fun open(spec:Map<String,Any?> = spec(),ids:List<ImageRegionIdentity> = identities)=WritableRegions(context,spec,ids,::read)
 }
 @Test fun independentCopiesAndGlobalLeasePreservePrimarySnapshotAndRealPerRegionGenerations(){val f=Fixture(temporary.resolve("lease"));f.open().use{s->assertEquals("primary",s.primaryRegionId);val before=s.regionSnapshots();val secondary=s.regionForWrite(second,4096);val tx=secondary.prepareErase(second,4096);assertFalse(s.snapshot().pending);assertTrue(s.regionSnapshots()[1].pending);assertFails{s.prepareProgram(first+4096,ByteBuffer.wrap(byteArrayOf(0)))};assertFails{s.prepareErase(first+4096,4096)};assertEquals(0L,s.state()["sequence"]);tx.close();assertEquals(before,s.regionSnapshots());assertFails{tx.commit()};assertEquals(1L,s.prepareErase(second,4096).commit().generation);val p=ByteBuffer.wrap(byteArrayOf(0x5a));val program=s.prepareProgram(second,p);assertEquals(0,p.position());p.put(0,0);assertEquals(2L,program.commit().generation);assertFails{program.commit()};val a=s.prepareProgram(first+4096,ByteBuffer.wrap(byteArrayOf(0x33))).commit();assertEquals(1L,a.generation);assertEquals(listOf(1L,2L),s.regionSnapshots().map{it.generation});assertEquals(3L,s.state()["sequence"]);assertEquals(listOf("secondary","secondary","primary"),(s.state()["journal"]as List<*>).map{(it as Map<*,*>)["regionId"]});assertEquals(0x5a.toByte(),Files.readAllBytes(f.home.resolve("copy-b.img"))[0]);assertEquals(0x33.toByte(),Files.readAllBytes(f.home.resolve("copy-a.img"))[4096]);f.identities.forEachIndexed{i,id->assertContentEquals(f.seeds[i],Files.readAllBytes(f.home.resolve(id.relativeFile)))}}}
 @Test fun gapsCrossRegionRangesCachedWrongHandlesAndPageBoundsRefuseBeforeMutation(){val f=Fixture(temporary.resolve("bounds"));f.open().use{s->val handle=s.regionForWrite(first+4096,1);val before=s.regionSnapshots();for((at,n)in listOf(-1L to 1L,first to 1L,first+8191 to 2L,first+8192 to 1L,first+4096 to second-first,second+8192 to 1L,Long.MAX_VALUE to 1L,0L to Long.MAX_VALUE)){assertFails{s.regionForWrite(at,n)};assertEquals(before,s.regionSnapshots())};assertFails{handle.prepareErase(second,4096)};for((at,n)in listOf(second to 0,first+4096 to 257,first+4096+255 to 2)){val p=ByteBuffer.wrap(ByteArray(n));assertFails{s.prepareProgram(at,p)};assertEquals(0,p.position());assertEquals(before,s.regionSnapshots())};assertEquals(0L,s.state()["sequence"])}}
 @Test fun malformedLaterRegionAndDuplicateIdsFilesOrUnknownSchemaCreateNoOutputs(){val cases=listOf<(Fixture)->Map<String,Any?>>({it.spec()+mapOf("schema" to 1.0)},{it.spec()+mapOf("extra" to 0)},{it.spec()+mapOf("primaryRegionId" to "absent")},{it.spec()+mapOf("regions" to listOf(it.child(0)))},{it.spec()+mapOf("regions" to List(9){_->it.child(0)})},{it.spec(listOf(it.child(0),it.child(0)))},{it.spec(listOf(it.child(0),it.child(1)+mapOf("file" to "copy-a.img")))},{it.spec(listOf(it.child(0),it.child(1)+mapOf("writableOffset" to second+1)))},{it.spec(listOf(it.child(0),it.child(1)+mapOf("programLaw" to "unknown")))},{it.spec(listOf(it.child(0),it.child(1)+mapOf("sha256" to "0".repeat(64))))},{it.spec(listOf(it.child(0),it.child(1)+mapOf("file" to "../escape.img")))})
  for((i,change)in cases.withIndex()){val f=Fixture(temporary.resolve("bad-"+i));assertFails{f.open(change(f))};assertFalse(Files.exists(f.home.resolve("copy-a.img")));assertFalse(Files.exists(f.home.resolve("copy-b.img")));assertFalse(Files.exists(f.home.resolve("copy-a.img.lock")))}}
 @Test fun overlappingSeedsAndExistingCopyOrLockAliasesAreRejectedBeforeFirstCreation(){val f=Fixture(temporary.resolve("overlap"));assertFails{f.open(ids=listOf(f.identities[0],f.identities[1].copy(offset=first+4096)))};assertFalse(Files.exists(f.home.resolve("copy-a.img")));for(lock in listOf(false,true)){val q=Fixture(temporary.resolve("alias-"+lock));Files.createLink(q.home.resolve(if(lock)"copy-b.img.lock" else "copy-b.img"),q.home.resolve("seed-b.img"));assertFails{q.open()};assertFalse(Files.exists(q.home.resolve("copy-a.img")));assertContentEquals(q.seeds[1],Files.readAllBytes(q.home.resolve("seed-b.img")))}}
 @Test fun failedSecondaryCommitRetainsFailureAndNeverProducesGlobalSuccessOrTouchesPrimary(){val f=Fixture(temporary.resolve("failure"));f.open().use{s->val tx=s.prepareErase(second,4096);val bytes=Files.readAllBytes(f.home.resolve("copy-b.img"));bytes[0]=0x12;Files.write(f.home.resolve("copy-b.img"),bytes);assertFails{tx.commit()};assertEquals(0L,s.state()["sequence"]);assertTrue((s.state()["journal"]as List<*>).isEmpty());assertNotNull(s.regionSnapshots()[1].failure);assertFails{s.prepareProgram(first+4096,ByteBuffer.wrap(byteArrayOf(0)))};assertContentEquals(f.seeds[0],Files.readAllBytes(f.home.resolve("copy-a.img")));tx.close()}}
 @Test fun closeCancelsSecondaryAndReleasesAllLocksAndResumePreservesOnlyExplicitBytes(){val f=Fixture(temporary.resolve("resume"));val s=f.open();s.prepareErase(second,4096).commit();s.prepareProgram(first+4096,ByteBuffer.wrap(byteArrayOf(0x12))).commit();val states=s.regionSnapshots();val pending=s.prepareProgram(second,ByteBuffer.wrap(byteArrayOf(0x23)));s.close();assertFails{pending.commit()};pending.close();assertTrue(s.regionSnapshots().all{it.closed&&!it.pending});assertFails{s.prepareErase(second,4096)};val children=(0..1).map{i->f.child(i)+mapOf("mode" to "resume","sha256" to states[i].currentSha256)};f.open(f.spec(children)).use{resumed->assertEquals(states.map{it.currentSha256},resumed.regionSnapshots().map{it.currentSha256});assertEquals(listOf(0L,0L),resumed.regionSnapshots().map{it.generation});assertEquals(0L,resumed.state()["sequence"])}}
 @Test fun aggregateJournalIsBoundedAndCanceledOperationsDoNotConsumeSequence(){val f=Fixture(temporary.resolve("journal"));f.open().use{s->repeat(130){val tx=s.prepareProgram(first+4096,ByteBuffer.wrap(byteArrayOf(-1)));tx.close();assertFails{tx.commit()}};assertEquals(0L,s.state()["sequence"]);repeat(129){s.prepareProgram(first+4096,ByteBuffer.wrap(byteArrayOf(-1))).commit()};assertEquals(129L,s.state()["sequence"]);assertEquals(true,s.state()["journalTruncated"]);val log=s.state()["journal"]as List<*>;assertEquals(128,log.size);assertEquals(2L,(log.first()as Map<*,*>)["sequence"])}}
 @Test fun actualFactoryPublishesOptionalSetAndReadOnlyOverlayCoversEveryCommittedDomain(){val f=Fixture(temporary.resolve("factory"));val rows=f.identities.map{mapOf("id" to it.id,"offset" to it.offset,"length" to it.length,"file" to it.relativeFile,"sha256" to it.sha256)};val context=Context(f.home,mapOf("regions.json" to mapOf("schema" to 1,"profile" to SupplementalRegions.PROFILE,"regions" to rows),"mutable.json" to f.spec()));val raw=ByteArray(0x274+4096);ByteBuffer.wrap(raw).order(ByteOrder.LITTLE_ENDIAN).putInt(0,6).putInt(0x24c,4096);context.claims["test.update"]=object:UpdateDataPort{override val size=raw.size.toLong();override val sha256=hash(raw);override fun read(offset:Long,destination:ByteBuffer){destination.put(raw,offset.toInt(),destination.remaining())}}
  val factory=FlashImageFactory();val config=factory.descriptor.settings.associate{it.key to it.default}+mapOf("sourcePort" to "test.update","regionsProfile" to SupplementalRegions.PROFILE,"regionsFile" to "regions.json","mutationProfile" to WritableRegions.PROFILE,"mutationFile" to "mutable.json")
  factory.create(context,config).use{component->val mutable=checkNotNull(context.ports.find("flash.image.mutable",WritableImagePort::class.java));assertTrue(mutable is WritableImageSetPort);val ro=checkNotNull(context.ports.find("flash.image",ReadOnlyImagePort::class.java));val program=checkNotNull(context.ports.find("flash.image.program",ProgrammableImagePort::class.java));mutable.prepareErase(second,4096).commit();program.prepareProgram(first+4096,ByteBuffer.wrap(byteArrayOf(0x41))).commit();program.prepareProgram(second,ByteBuffer.wrap(byteArrayOf(0x52))).commit();for((at,value)in listOf(first+4096 to 0x41,second to 0x52)){val destination=ByteBuffer.allocateDirect(4);destination.position(1);destination.limit(2);ro.read(at,destination);assertEquals(2,destination.position());assertEquals(value.toByte(),destination.get(1))};val denied=ByteBuffer.allocate(4);assertFails{ro.read(first+8192,denied)};assertEquals(0,denied.position());val state=component.state()["writableRegionSet"]as Map<*,*>;assertEquals(3L,state["sequence"]);assertEquals("primary",(component.state()["writableOverlay"]as WritableImageState).regionId)}
 }
}
